-- D-55 / D-60 / appendix D. Official accounts and reserved names.
--
-- Depends on migrate-20251219.sql (username.editable/active/order2),
-- migrate-20261030-email.sql (users.phone is nullable), and
-- migrate-20261029-channels.sql. File order runs this after
-- migrate-20261104-tellomi-username.sql, which parked @tellomi on the
-- existing service user 777000. This file moves @tellomi to user 777001.
--
-- Appendix D: phase 1 of @tellomi is an official user. Phase 2 registers
-- it as a bot. User 777000 stays the service account the process already
-- uses for login codes (user_type 4, first_name Tellomi). Its primary
-- username becomes @admin.
--
-- A peer can own more than one username row (same peer_type and peer_id).
-- The first name in each appendix D cell is the primary (editable = 1).
-- The other names on that account are active and editable = 0.
--
-- Bots are not inserted. bots.createBot stores bots in process memory
-- (app/bff/botadmin) and BotsDAO has no insert, so a users plus bots row
-- would not be a bot that runtime can operate. Those names are empty
-- placeholders: peer_type 0, peer_id 0, active 0. account.checkUsername
-- still returns USERNAME_OCCUPIED because it matches any username row.
-- user.resolveUsername returns USERNAME_NOT_OCCUPIED for peer_type 0
-- until a later change points the row at a real peer.
--
-- Channels are stored the same way the channel service reads them
-- (channels, channel_participants, channel_feature). Ids sit above
-- MinNebulaChatChannelID (1073741824). channel_id_counter is moved past
-- them. There is no opening service message, so history is empty.
-- The creator participant is user 777002. Role 1 is the creator; the
-- reader fills admin rights for that role.
-- default_banned_rights is the value CreateChannel stores: EditRank,
-- ChangeInfo, and PinMessages banned, until date 2147483647 in the high
-- 32 bits (9223372032627049472).
--
-- Names in appendix C that appendix D does not assign are not written.
-- username.id is AUTO_INCREMENT. New users are 777001 through 777005.
-- phone is NULL (the unique phone index allows many NULLs). These users
-- have no auth key and cannot sign in. allowlist.toml is in the
-- tellomi/tellomi policy repository, not this one.
--
-- If a name or id already belongs to someone else, the script stops and
-- does not take it (D-26). @tellomi may still point at 777000 from D-27;
-- that row is moved, not treated as a conflict. A second run changes
-- nothing.

SET @bad = (SELECT username FROM username WHERE (username = 'tellomi' AND peer_id NOT IN (777000, 777001)) OR (username = 'tellomi_official' AND NOT (peer_type = 2 AND peer_id = 777002)) OR (username = 'tellomiapp' AND NOT (peer_type = 2 AND peer_id = 777002)) OR (username = 'tellomi_team' AND NOT (peer_type = 2 AND peer_id = 777003)) OR (username = 'support' AND NOT (peer_type = 2 AND peer_id = 777004)) OR (username = 'tellomi_support' AND NOT (peer_type = 2 AND peer_id = 777004)) OR (username = 'kefu' AND NOT (peer_type = 2 AND peer_id = 777004)) OR (username = 'customer_support' AND NOT (peer_type = 2 AND peer_id = 777004)) OR (username = 'customer_service' AND NOT (peer_type = 2 AND peer_id = 777004)) OR (username = 'faxian' AND NOT (peer_type = 2 AND peer_id = 777005)) OR (username = 'discover' AND NOT (peer_type = 2 AND peer_id = 777005)) OR (username = 'admin' AND NOT (peer_type = 2 AND peer_id = 777000)) OR (username = 'tellomi_admin' AND NOT (peer_type = 2 AND peer_id = 777000)) OR (username = 'administrator' AND NOT (peer_type = 2 AND peer_id = 777000)) OR (username = 'system' AND NOT (peer_type = 2 AND peer_id = 777000)) OR (username = 'xitong' AND NOT (peer_type = 2 AND peer_id = 777000)) OR (username = 'noreply' AND NOT (peer_type = 2 AND peer_id = 777000)) OR (username = 'notifications' AND NOT (peer_type = 2 AND peer_id = 777000)) OR (username = 'news' AND NOT (peer_type = 4 AND peer_id = 1073800001)) OR (username = 'gonggao' AND NOT (peer_type = 4 AND peer_id = 1073800001)) OR (username = 'announcement' AND NOT (peer_type = 4 AND peer_id = 1073800001)) OR (username = 'notice' AND NOT (peer_type = 4 AND peer_id = 1073800001)) OR (username = 'updates' AND NOT (peer_type = 4 AND peer_id = 1073800002)) OR (username = 'security' AND NOT (peer_type = 4 AND peer_id = 1073800003)) OR (username = 'tellomi_security' AND NOT (peer_type = 4 AND peer_id = 1073800003)) OR (username = 'anquan' AND NOT (peer_type = 4 AND peer_id = 1073800003)) OR (username = 'safety' AND NOT (peer_type = 4 AND peer_id = 1073800003)) OR (username = 'trust' AND NOT (peer_type = 4 AND peer_id = 1073800003)) OR (username = 'dev' AND NOT (peer_type = 4 AND peer_id = 1073800004)) OR (username = 'developer' AND NOT (peer_type = 4 AND peer_id = 1073800004)) OR (username = 'api' AND NOT (peer_type = 4 AND peer_id = 1073800004)) OR (username = 'help' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'helpcenter' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'help_center' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'bangzhu' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'verify' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'tellomi_verify' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'verified' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'renzheng' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'report' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'jubao' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'abuse' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'feedback' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'fankui' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'bots' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'premium' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'vip' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'huiyuan' AND NOT (peer_type = 0 AND peer_id = 0)) OR (username = 'stickers' AND NOT (peer_type = 0 AND peer_id = 0)) LIMIT 1);
CALL teamgram_fail_if_set(@bad, 'D-55: official username taken: ');

SET @bad_user = (SELECT CAST(id AS CHAR) FROM users WHERE (id = 777001 AND NOT (user_type = 2 AND username IN ('tellomi', ''))) OR (id = 777002 AND NOT (user_type = 2 AND username IN ('tellomi_official', ''))) OR (id = 777003 AND NOT (user_type = 2 AND username IN ('tellomi_team', ''))) OR (id = 777004 AND NOT (user_type = 2 AND username IN ('support', ''))) OR (id = 777005 AND NOT (user_type = 2 AND username IN ('faxian', ''))) OR (id = 777000 AND NOT (user_type = 4 AND username IN ('tellomi', 'telegram', 'teamgram', 'admin', ''))) LIMIT 1);
CALL teamgram_fail_if_set(@bad_user, 'D-55: official user id is already a different account: ');

SET @bad_channel = (SELECT CAST(id AS CHAR) FROM channels WHERE (id = 1073800001 AND NOT (username <=> 'news')) OR (username = 'news' AND id <> 1073800001) OR (id = 1073800002 AND NOT (username <=> 'updates')) OR (username = 'updates' AND id <> 1073800002) OR (id = 1073800003 AND NOT (username <=> 'security')) OR (username = 'security' AND id <> 1073800003) OR (id = 1073800004 AND NOT (username <=> 'dev')) OR (username = 'dev' AND id <> 1073800004) LIMIT 1);
CALL teamgram_fail_if_set(@bad_channel, 'D-55: official channel id or username is taken: ');

INSERT IGNORE INTO users (id, user_type, access_hash, secret_key_id, first_name, last_name, username, phone, country_code, verified, support, about, is_bot) VALUES (777001, 2, 8100000000000777001, 0, 'Tellomi', '', 'tellomi', NULL, '', 1, 0, '', 0), (777002, 2, 8100000000000777002, 0, 'Tellomi', '', 'tellomi_official', NULL, '', 1, 0, '', 0), (777003, 2, 8100000000000777003, 0, 'Tellomi Team', '', 'tellomi_team', NULL, '', 1, 0, '', 0), (777004, 2, 8100000000000777004, 0, 'Tellomi Support', '', 'support', NULL, '', 1, 1, '', 0), (777005, 2, 8100000000000777005, 0, '发现', '', 'faxian', NULL, '', 1, 0, '', 0);
SET @teamgram_stmt = 'UPDATE users SET username = ''admin'' WHERE id = 777000 AND username IN (''tellomi'', ''telegram'', ''teamgram'', '''')';
PREPARE teamgram_ps FROM @teamgram_stmt;
EXECUTE teamgram_ps;
DEALLOCATE PREPARE teamgram_ps;

